T018,Iterate on model based on feedback,To Do,Ravi Kumar,Medium,Sprint 7,2026-06-30,Evaluation,"Adjust features, retrain model, validate improvements"
T019,Prepare production deployment plan,To Do,James Wong,High,Sprint 8,2026-07-07,Deployment,"Infrastructure scaling, rollback plan, monitoring setup"
T020,Staff training program,To Do,Sarah Lin,Medium,Sprint 8,2026-07-14,Deployment,"Train 25 logistics staff on using AI-powered forecasting dashboard"
T021,Full production rollout,To Do,Arjun Mehta,High,Sprint 9,2026-07-21,Deployment,"Go-live for demand forecasting across all 3 distribution centers"
T022,Set up continuous monitoring,To Do,Priya Nair,High,Sprint 9,2026-07-28,Monitoring,"Model performance dashboards, drift detection alerts, retraining triggers"
T023,Project closure report,To Do,Arjun Mehta,Medium,Sprint 10,2026-08-04,Monitoring,"Final report: outcomes vs targets, lessons learned, recommendations for Phase 2"
T024,Security review of AI infrastructure,Blocked,James Wong,High,Sprint 5,2026-05-26,Security,"Penetration testing and vulnerability assessment - BLOCKED: waiting for security team availability"
T025,Legal review of data usage,In Progress,Sarah Lin,High,Sprint 3,2026-04-28,Compliance,"Review data privacy compliance for using customer delivery data in ML models"`;

// ---------- Helpers ----------
function parseCsv(text) {
  const rows = [];
  let row = [], field = '', inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') inQuotes = false;
      else field += c;
    } else if (c === '"') inQuotes = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.some((v) => v.trim() !== '')) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some((v) => v.trim() !== '')) rows.push(row);
  const [header, ...body] = rows;
  return body.map((r) => Object.fromEntries(header.map((h, i) => [h.trim(), (r[i] ?? '').trim()])));
}

const DAY = 86400000;
const toDate = (s) => { const [y, m, d] = s.split('-').map(Number); return new Date(Date.UTC(y, m - 1, d)); };
const fmt = (d) => d.toISOString().slice(0, 10);
const addDays = (d, n) => new Date(d.getTime() + n * DAY);
const daysBetween = (a, b) => Math.round((b - a) / DAY);
const countBy = (arr, key) => arr.reduce((acc, x) => ({ ...acc, [x[key]]: (acc[x[key]] ?? 0) + 1 }), {});

const asOf = toDate(cfg.asOfDate);
const projectStart = toDate(cfg.projectStartDate);
const upcomingEnd = addDays(asOf, Number(cfg.upcomingWindowDays));
const dueSoonEnd = addDays(asOf, Number(cfg.dueSoonDays));
const STATUSES = ['Done', 'In Progress', 'Blocked', 'To Do'];

// ---------- Timeline: week numbers -> calendar dates ----------
const timeline = parseCsv(TIMELINE_CSV).map((p) => {
  const start = addDays(projectStart, (Number(p.start_week) - 1) * 7);
  const end = addDays(projectStart, Number(p.end_week) * 7 - 1);
  const status = end < asOf ? 'Completed (by schedule)' : start > asOf ? 'Upcoming' : 'Current';
  return {
    phase: Number(p.phase),
    phase_name: p.phase_name,
    start_week: Number(p.start_week),
    end_week: Number(p.end_week),
    start_date: fmt(start),
    end_date: fmt(end),
    schedule_status: status,
    key_activities: p.key_activities.split(';').map((s) => s.trim()).filter(Boolean),
    milestones: p.milestones_deliverables.split(';').map((s) => s.trim()).filter(Boolean),
  };
});

// Each milestone is due at the end of its phase.
const milestones = timeline.flatMap((p) => p.milestones.map((m) => ({
  milestone: m,
  phase: p.phase,
  phase_name: p.phase_name,
  due_week: p.end_week,
  due_date: p.end_date,
  days_from_as_of: daysBetween(asOf, toDate(p.end_date)),
})));

// ---------- Project outcome phrases ----------
// Short verbatim phrases from the description (goals, use cases, capabilities). Agents cite these
// from a fixed list instead of free-text quoting, so a citation can never be invented.
const LEAD = /^(and|or|including|include|includes|the company aims to|aims to|by leveraging|by|to|of|with|is embarking on an ai adoption initiative to|key goals include|this project will focus on|beginning with|followed by|will)\s+/i;
const outcomePhrases = [...new Set(PROJECT_DESCRIPTION.split('\n').slice(1).join(' ')
  .split(/[.;,]|\s+and\s+(?=[a-z]+ing\b|improv|reduc|lower|minim|uncov|drive|enhanc)/)
  .map((s) => { let t = s.trim(), prev; do { prev = t; t = t.replace(LEAD, ''); } while (t !== prev); return t; })
  .filter((s) => { const n = s.split(/\s+/).length; return n >= 2 && n <= 9 && !/ABCDE|^This|^The /.test(s); }))];
const USE_CASES = ['demand forecasting', 'route optimization', 'inventory management', 'customer support']
  .filter((u) => PROJECT_DESCRIPTION.toLowerCase().includes(u));

// ---------- Risks ----------
const risks = parseCsv(RISKS_CSV);

// ---------- Tasks ----------
const tasks = parseCsv(TASKS_CSV).map((t) => {
  const due = toDate(t.due_date);
  return { ...t, days_until_due: daysBetween(asOf, due) };
});
const open = (t) => t.status !== 'Done';

const statusCounts = Object.fromEntries(STATUSES.map((s) => [s, tasks.filter((t) => t.status === s).length]));
const unknownStatuses = tasks.filter((t) => !STATUSES.includes(t.status)).map((t) => `${t.task_id}: ${t.status}`);

const sprintNames = [...new Set(tasks.map((t) => t.sprint))]
  .sort((a, b) => Number(a.replace(/\D/g, '')) - Number(b.replace(/\D/g, '')));
const sprints = sprintNames.map((name) => {
  const ts = tasks.filter((t) => t.sprint === name);
  const dues = ts.map((t) => t.due_date).sort();
  return {
    sprint: name,
    first_due: dues[0],
    last_due: dues[dues.length - 1],
    task_count: ts.length,
    status_counts: Object.fromEntries(STATUSES.map((s) => [s, ts.filter((t) => t.status === s).length])),
    task_ids: ts.map((t) => t.task_id),
  };
});
// Current sprint = first sprint whose last due date has not passed.
const currentSprint = (sprints.find((s) => toDate(s.last_due) >= asOf) ?? sprints[sprints.length - 1]).sprint;

const brief = (t) => ({
  task_id: t.task_id, task_name: t.task_name, status: t.status, assignee: t.assignee,
  priority: t.priority, sprint: t.sprint, due_date: t.due_date, days_until_due: t.days_until_due,
});

const blocked = tasks.filter((t) => t.status === 'Blocked').map((t) => ({ ...brief(t), description: t.description }));
const overdue = tasks.filter((t) => open(t) && toDate(t.due_date) < asOf).map(brief);
const dueSoon = tasks.filter((t) => open(t) && t.status !== 'Blocked'
  && toDate(t.due_date) >= asOf && toDate(t.due_date) <= dueSoonEnd).map(brief);

const workload = Object.entries(countBy(tasks.filter(open), 'assignee'))
  .map(([assignee, open_tasks]) => ({
    assignee,
    open_tasks,
    open_high_priority: tasks.filter((t) => open(t) && t.assignee === assignee && t.priority === 'High').length,
    in_progress: tasks.filter((t) => t.status === 'In Progress' && t.assignee === assignee).map((t) => t.task_id),
  }))
  .sort((a, b) => b.open_tasks - a.open_tasks);

const currentWeek = Math.floor(daysBetween(projectStart, asOf) / 7) + 1;
const currentPhase = timeline.find((p) => p.schedule_status === 'Current') ?? null;

const facts = {
  as_of_date: fmt(asOf),
  project_start_date: fmt(projectStart),
  current_week: currentWeek,
  total_weeks: Math.max(...timeline.map((p) => p.end_week)),
  current_phase: currentPhase ? `Phase ${currentPhase.phase}: ${currentPhase.phase_name}` : 'None (outside timeline)',
  current_sprint: currentSprint,
  total_tasks: tasks.length,
  status_counts: statusCounts,
  completion_pct: Math.round((statusCounts.Done / tasks.length) * 100),
  blocked_tasks: blocked,
  overdue_tasks: overdue,
  due_soon_tasks: dueSoon,
  due_soon_window: `${fmt(asOf)} to ${fmt(dueSoonEnd)}`,
  upcoming_milestones: milestones.filter((m) => m.days_from_as_of >= 0 && toDate(m.due_date) <= upcomingEnd),
  upcoming_window: `${fmt(asOf)} to ${fmt(upcomingEnd)}`,
  next_milestones_after_window: milestones.filter((m) => toDate(m.due_date) > upcomingEnd).slice(0, 2),
  sprints,
  workload,
  risk_count: risks.length,
  risk_categories: risks.map((r) => `${r.risk_id} ${r.category}`),
  data_warnings: unknownStatuses.map((s) => `Unrecognised task status: ${s}`),
};

return [{
  json: {
    project: { name: PROJECT_NAME, description: PROJECT_DESCRIPTION.trim(), outcome_phrases: outcomePhrases, use_cases: USE_CASES },
    timeline,
    milestones,
    risks,
    tasks,
    facts,
  },
}];

// Baseline test dataset (eval_mira_inputs.txt) with machine-checkable expectations.
// Emits one item per test listed in RUN – or, when started from the Chat Trigger, the chat message.

const incoming = $input.first()?.json ?? {};
if (incoming.chatInput) {
  return [{ json: { test_id: 'chat', query: incoming.chatInput, session_id: incoming.sessionId ?? null, checks: [] } }];
}

const RUN = ["T3", "T4", "T7"];
const WITH_ROUTE = false; // full Mira workflow: also check the Orchestrator's route
const JUDGE_MATERIAL_MAX = null; // with the Fact-Check Judge: advisory max material claims (null = no judge)

// Check types: status (value or list of accepted values) | judge_material_max | judge_min | phase_count | field (output field equals value) | grounded_min |
// mentions_all / mentions_any / not_mentions (case-insensitive, in rendered output)
// route: the agent the Orchestrator should pick (checked only when WITH_ROUTE).
const TESTS = [
  { test_id: 'T1', query: 'Generate a project plan for the AI Adoption Project at ABCDE Ltd. Use the provided project description.', route: 'planner',
    checks: [{ type: 'status', value: 'PLAN' }, { type: 'phase_count', value: 8 }, { type: 'grounded_min', value: 0.9 }] },
  { test_id: 'T2', query: 'Generate a project plan for: "We want to build a chatbot."', route: 'clarifier',
    checks: [{ type: 'status', value: 'NEEDS_CLARIFICATION' }, { type: 'mentions_all', value: ['scope', 'timeline', 'team'] }] },
  { test_id: 'T3', query: 'Generate a risk assessment for the AI Adoption Project at ABCDE Ltd. Use the provided project description.', route: 'risk',
    checks: [{ type: 'status', value: 'ASSESSMENT' }, { type: 'field', field: 'risk_count', value: 10 }, { type: 'grounded_min', value: 0.9 },
      { type: 'field', field: 'review_issue_count', value: 0 },
      { type: 'mentions_any', value: ['logistics', 'route', 'forecast', 'delivery', 'inventory'] }] },
  { test_id: 'T4', query: 'Generate a risk assessment for: "New project starting soon."', route: 'clarifier',
    checks: [{ type: 'status', value: 'NEEDS_CLARIFICATION' }, { type: 'mentions_all', value: ['scope', 'timeline'] },
      { type: 'not_mentions', value: ['R01', 'R02', 'Data Quality', 'Likelihood'] }] },
  { test_id: 'T5', query: 'Generate a weekly status report using the sample task board data for Sprint 3.', route: 'status',
    checks: [{ type: 'status', value: 'REPORT' }, { type: 'field', field: 'scope', value: 'Sprint 3' },
      { type: 'field', field: 'counts', value: 'Done 0 · In Progress 2 · Blocked 0 · To Do 2' },
      { type: 'mentions_all', value: ['Shortlist AI use cases', 'Define success criteria for each use case', 'Vendor evaluation for ML platform', 'Legal review of data usage'] },
      { type: 'grounded_min', value: 0.9 }] },
  { test_id: 'T6', query: 'Generate a weekly status report for: "Things are going fine."', route: 'clarifier',
    checks: [{ type: 'status', value: ['NO_DATA', 'NEEDS_CLARIFICATION'] }, { type: 'mentions_all', value: ['no task data'] },
      { type: 'not_mentions', value: ['%', 'T0'] }] },
  { test_id: 'T7', query: 'What are the top 3 risks for the ABCDE Ltd project based on the risk data?', route: 'risk',
    checks: [{ type: 'status', value: 'TOP_RISKS' }, { type: 'field', field: 'risk_count', value: 3 },
      { type: 'field', field: 'assessed_count', value: 10 }, { type: 'grounded_min', value: 0.9 },
      { type: 'field', field: 'review_issue_count', value: 0 }] },
  { test_id: 'T8', query: 'Which tasks are blocked or at risk of missing their deadline based on the task board?', route: 'milestone',
    checks: [{ type: 'status', value: 'ALERTS' }, { type: 'field', field: 'blocked', value: 'T024' }, { type: 'field', field: 'overdue', value: 'T006' },
      { type: 'mentions_all', value: ['T024', 'Security review of AI infrastructure', 'T006'] }, { type: 'grounded_min', value: 0.9 }] },
  { test_id: 'T9', query: 'Generate a project plan for a 2-week project with no details provided.', route: 'clarifier',
    checks: [{ type: 'status', value: 'NEEDS_CLARIFICATION' }, { type: 'mentions_all', value: ['scope', 'goal', 'deliverable'] }] },
  { test_id: 'T10', query: 'Summarize the current project status: how many tasks are done, in progress, and to do?', route: 'status',
    checks: [{ type: 'status', value: 'REPORT' }, { type: 'field', field: 'scope', value: 'Whole project' },
      { type: 'field', field: 'counts', value: 'Done 5 · In Progress 3 · Blocked 1 · To Do 16' }, { type: 'grounded_min', value: 0.9 }] },
  { test_id: 'T11', query: 'What milestones are coming up in the next 2 weeks based on the timeline?', route: 'milestone',
    checks: [{ type: 'status', value: 'ALERTS' }, { type: 'field', field: 'upcoming_count', value: 2 },
      { type: 'mentions_all', value: ['Current systems audit report', 'Gap analysis report'] }, { type: 'grounded_min', value: 0.9 }] },
  { test_id: 'T12', query: 'Generate a stakeholder update email summarizing Sprint 2 progress.', route: 'comms',
    checks: [{ type: 'status', value: 'EMAIL' }, { type: 'field', field: 'scope', value: 'Sprint 2' },
      { type: 'mentions_all', value: ['Audit existing data infrastructure', 'Map current logistics workflows', 'Identify data gaps'] },
      { type: 'not_mentions', value: ['Shortlist AI use cases', 'Legal review of data usage', 'Security review', 'Vendor evaluation', 'T007', 'T024', 'T025'] },
      { type: 'grounded_min', value: 0.9 }] },
  // Extra robustness case (not in the baseline dataset).
  { test_id: 'X1', query: 'What is the weather in Paris tomorrow?', route: 'fallback',
    checks: [{ type: 'status', value: 'OUT_OF_SCOPE' }] },
];

return TESTS.filter((t) => RUN.includes(t.test_id)).map(({ route, ...t }) => ({
  json: {
    ...t,
    checks: [
      ...(WITH_ROUTE && route ? [{ type: 'field', field: 'route', value: route }] : []),
      ...t.checks,
      ...(JUDGE_MATERIAL_MAX !== null ? [{ type: 'judge_material_max', value: JUDGE_MATERIAL_MAX, advisory: true }] : []),
    ],
  },
}));

// Risk Assessor – builds the OpenAI request for each incoming request item.
// The model only rates and links register risks by ID (one schema key per risk); risk text and
// mitigations are copied from project_risks.csv by code, so no risk can be invented.

const cfg = $('Config').first().json;
const kb = $('Knowledge Base').first().json;

const SYSTEM_PROMPT = `ROLE
You are the Risk Assessor inside Mira, a project intelligence assistant for PMs/TPMs at Nexora. You assess a project's risks using only its risk register and project data, and you refuse to assess when there is no project data.

INPUT
- USER REQUEST: what the PM asked for.
- PROJECT DATA (optional): <project_description>, <schedule> (phases with schedule status), <task_board> (tasks with status and due dates, plus blocked/overdue lists) and <risk_register> (risks R01..Rnn). If PROJECT DATA is absent, the only information you have is the USER REQUEST text.

DECISION – choose exactly one status
1. PROJECT DATA is absent → status "NEEDS_CLARIFICATION". A risk assessment needs a known project; never produce risks from a one-line request.
2. PROJECT DATA is present and the PM asks for the top / most important / biggest N risks → status "TOP_RISKS", requested_count = N (default 3).
3. PROJECT DATA is present otherwise → status "ASSESSMENT", requested_count = number of risks in the register.

RULES FOR AN ASSESSMENT (both TOP_RISKS and ASSESSMENT) – hallucination guardrails
- summary: 2–3 sentences on the overall risk picture for this project at its current phase. Do not number or rank risks in the summary; ranking is computed separately.
- risks has one entry per register risk ID. Fill in EVERY entry, also when the PM asks only for the top N – the top N are selected by code from your ratings. Do not create risks that are not in the register.
- likelihood and impact (High / Medium / Low) must reflect THIS project: its logistics domain, its use cases (demand forecasting, route optimization, inventory management, customer support), the current phase, and live task-board signals. Do not rate everything High.
- If any related task is Blocked or Overdue, likelihood must be Medium or High – the problem is already showing.
- priority_rank: your overall order 1..n (1 = most urgent), unique per risk. Use it to break ties between equal ratings.
- rationale: 1–2 sentences on why this risk matters for this project now. Cite a specific project fact – a use case, goal, phase, or task ID. Never use generic statements such as "this is common in AI projects".
- evidence_quote: choose from the allowed list the project goal, use case or capability this risk threatens most (e.g. "route optimization", "reducing delivery delays by 15%"). Prefer the most specific phrase.
- affected_use_cases: the 1–2 logistics use cases this risk would hit HARDEST, so the PM can see where each risk bites (e.g. data-quality risk → demand forecasting, inventory management; legacy-integration risk → route optimization). Do not list every use case for every risk. Use an empty array only if the risk is truly organisation-wide.
- related_task_ids: task IDs from <task_board> that are signals for this risk (e.g. a blocked security review → security risk). Empty array if none. Never use IDs that are not on the board.
- exposed_phase: the phase number from <schedule> where this risk is most likely to materialise.
- owner_role: who on the cross-functional task force should own it.
- next_step: one full sentence (8–30 words) stating a concrete action that applies the register's mitigation to THIS project – what to do, and on which use case, data, system or task. Do not copy the mitigation text and do not just name a phase. Example for a data risk: "Run a data-quality audit of historical delivery and inventory records and close the gaps found in T006."
- next_step_before_phase: the phase number by whose start the next step must be done. It must be the current phase or a later one.

RULES FOR NEEDS_CLARIFICATION
- Set assessment to null. Do NOT list risks, generic or otherwise.
- reason: one sentence on why risks cannot be assessed yet.
- known_information: what the request does state (may be empty).
- missing_information: always cover project scope and objectives, industry/domain, timeline and current phase, team size/roles, technology and systems involved, budget, and key stakeholders/dependencies – unless explicitly given.
- questions: 4–7 specific questions the PM can answer to unblock the assessment.

OUTPUT
Return JSON matching the provided schema. Unused branch must be null.`;

const riskIds = kb.risks.map((r) => r.risk_id);
const taskIds = kb.tasks.map((t) => t.task_id);
const phaseNumbers = kb.timeline.map((p) => p.phase);
const level = { type: 'string', enum: ['High', 'Medium', 'Low'] };
const strings = { type: 'array', items: { type: 'string' } };

// One required key per register risk: strict mode then forces the model to rate all of them.
const riskRating = {
  type: 'object', additionalProperties: false,
  required: ['likelihood', 'impact', 'priority_rank', 'rationale', 'evidence_quote', 'affected_use_cases',
    'related_task_ids', 'exposed_phase', 'owner_role', 'next_step', 'next_step_before_phase'],
  properties: {
    likelihood: level,
    impact: level,
    priority_rank: { type: 'integer' },
    rationale: { type: 'string' },
    // Verbatim description phrases extracted by the Knowledge Base – a citation can't be invented.
    evidence_quote: { type: 'string', enum: kb.project.outcome_phrases },
    affected_use_cases: { type: 'array', items: { type: 'string', enum: kb.project.use_cases } },
    related_task_ids: { type: 'array', items: { type: 'string', enum: taskIds } },
    exposed_phase: { type: 'integer', enum: phaseNumbers },
    owner_role: { type: 'string', enum: ['Data scientists', 'IT professionals', 'Business stakeholders', 'Cross-functional task force'] },
    next_step: { type: 'string' },
    next_step_before_phase: { type: 'integer', enum: phaseNumbers },
  },
};

const RESPONSE_FORMAT = {
  type: 'json_schema',
  json_schema: {
    name: 'risk_output',
    strict: true,
    schema: {
      type: 'object', additionalProperties: false, required: ['status', 'clarification', 'assessment'],
      properties: {
        status: { type: 'string', enum: ['ASSESSMENT', 'TOP_RISKS', 'NEEDS_CLARIFICATION'] },
        clarification: {
          anyOf: [{ type: 'null' }, {
            type: 'object', additionalProperties: false,
            required: ['reason', 'known_information', 'missing_information', 'questions'],
            properties: { reason: { type: 'string' }, known_information: strings, missing_information: strings, questions: strings },
          }],
        },
        assessment: {
          anyOf: [{ type: 'null' }, {
            type: 'object', additionalProperties: false,
            required: ['requested_count', 'summary', 'risks'],
            properties: {
              requested_count: { type: 'integer' },
              summary: { type: 'string' },
              risks: {
                type: 'object', additionalProperties: false, required: riskIds,
                properties: Object.fromEntries(riskIds.map((id) => [id, riskRating])),
              },
            },
          }],
        },
      },
    },
  },
};

// The Orchestrator decides this (uses_project_on_file); the regex is the fallback for the standalone step workflows.
const refersToProject = (q) => /ABCDE|AI Adoption Project/i.test(q);

function projectDataBlock() {
  const f = kb.facts;
  const schedule = kb.timeline.map((p) =>
    `Phase ${p.phase}: ${p.phase_name} | ${p.start_date} to ${p.end_date} | ${p.schedule_status}`).join('\n');
  const tasks = kb.tasks.map((t) =>
    `${t.task_id} | ${t.task_name} | ${t.status} | ${t.priority} | ${t.sprint} | due ${t.due_date}`).join('\n');
  const listIds = (ts) => (ts.length ? ts.map((t) => `${t.task_id} ${t.task_name}`).join('; ') : 'none');
  const register = kb.risks.map((r) =>
    `${r.risk_id} | ${r.category} | ${r.risk_challenge} | Impact: ${r.impact} | Mitigation: ${r.mitigation_strategy}`).join('\n');
  return `PROJECT DATA – ${kb.project.name}\n` +
    `<project_description>\n${kb.project.description}\n</project_description>\n` +
    `<schedule>\nAs of ${f.as_of_date} (week ${f.current_week} of ${f.total_weeks}); current phase: ${f.current_phase}.\n${schedule}\n</schedule>\n` +
    `<task_board>\nTask | Name | Status | Priority | Sprint | Due\n${tasks}\n` +
    `Blocked: ${listIds(f.blocked_tasks)}\nOverdue: ${listIds(f.overdue_tasks)}\n</task_board>\n` +
    `<risk_register>\n${register}\n</risk_register>`;
}

return $input.all().map(({ json: req }) => {
  const usesProjectData = req.uses_project_on_file ?? refersToProject(req.query);
  const userContent = `USER REQUEST:\n${req.query}\n\n` +
    (usesProjectData ? projectDataBlock() : 'PROJECT DATA: none provided.');
  const messages = [
    { role: 'system', content: SYSTEM_PROMPT },
    { role: 'user', content: userContent },
  ];
  return {
    json: {
      ...req,
      agent: 'Risk Assessor',
      uses_project_data: usesProjectData,
      source_text: usesProjectData ? kb.project.description : req.query,
      started_at: new Date().toISOString(),
      openaiRequest: {
        model: cfg.model,
        temperature: Number(cfg.temperature),
        max_tokens: Number(cfg.maxTokens),
        response_format: RESPONSE_FORMAT,
        messages,
      },
    },
  };
});

// Risk Assessor – parses the model output, verifies it against the risk register and task board,
// ranks risks in code (likelihood × impact, model rank as tie-break), renders Markdown,
// and describes the LangSmith trace for this request.

const kb = $('Knowledge Base').first().json;
const requests = $('Risk Assessor: Build Prompt').all();

const SCORE = { High: 3, Medium: 2, Low: 1 };
const register = new Map(kb.risks.map((r) => [r.risk_id, r]));
const tasksById = new Map(kb.tasks.map((t) => [t.task_id, t]));
const phases = new Map(kb.timeline.map((p) => [p.phase, p]));

const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9%]+/g, ' ').trim();

// Quote must appear as a contiguous word sequence in the source, tolerating inflection only
// ("reduce" ≈ "reducing"): each word is compared on its first 5 letters.
const stems = (s) => norm(s).split(' ').filter(Boolean).map((w) => w.slice(0, 5));
function quoteInSource(quote, source) {
  const q = stems(quote), src = stems(source);
  if (!q.length) return false;
  for (let i = 0; i + q.length <= src.length; i++) {
    if (q.every((w, j) => src[i + j] === w)) return true;
  }
  return false;
}
const cell = (s) => String(s ?? '').replace(/\|/g, '/').replace(/\n/g, ' ');
const list = (items) => (items.length ? items.map((x) => `- ${x}`).join('\n') : '- _None._');

// Every assessed risk must exist in the register exactly once, cite the description verbatim,
// and link only to real tasks and phases.
function groundingCheck(a, req) {
  const issues = [];
  let checked = 0, grounded = 0;
  const seen = new Set();

  for (const r of a.risks) {
    checked++;
    const problems = [];
    if (!register.has(r.risk_id)) problems.push('not in register');
    if (seen.has(r.risk_id)) problems.push('duplicate');
    seen.add(r.risk_id);
    if (!quoteInSource(r.evidence_quote, req.source_text)) problems.push(`quote not in description → “${r.evidence_quote}”`);
    const unknownTasks = r.related_task_ids.filter((id) => !tasksById.has(id));
    if (unknownTasks.length) problems.push(`unknown tasks ${unknownTasks.join(', ')}`);
    if (!phases.has(r.exposed_phase)) problems.push(`unknown phase ${r.exposed_phase}`);
    if (problems.length) issues.push(`${r.risk_id}: ${problems.join(', ')}`);
    else grounded++;
  }
  const missing = kb.risks.map((r) => r.risk_id).filter((id) => !seen.has(id));
  if (missing.length) issues.push(`register risks not assessed: ${missing.join(', ')}`);

  return { checked, grounded, score: checked ? grounded / checked : 1, issues };
}

// Review checks: ratings must agree with the task board (a blocked or overdue linked task means the
// risk is already showing); next steps must be a real action, not the register text or a bare phase
// reference; and their deadline must not already be in the past.
const overdueIds = new Set(kb.facts.overdue_tasks.map((t) => t.task_id));
const currentPhase = kb.timeline.find((p) => p.schedule_status === 'Current')?.phase ?? 1;
const phaseWords = new Set(kb.timeline.flatMap((p) => norm(p.phase_name).split(' ')).concat(['before', 'by', 'phase', 'start', 'of', 'the']));
function reviewCheck(risks) {
  const allCases = kb.project.use_cases.length;
  const undifferentiated = risks.filter((r) => r.affected_use_cases.length >= allCases).length;
  const domain = !risks.some((r) => r.affected_use_cases.length) ? ['no risk is tied to a logistics use case']
    : undifferentiated > risks.length / 2 ? [`${undifferentiated}/${risks.length} risks list every use case – not differentiated`] : [];
  return domain.concat(risks.flatMap((r) => {
    const issues = [];
    const live = r.related_task_ids.filter((id) => tasksById.get(id)?.status === 'Blocked' || overdueIds.has(id));
    if (r.likelihood === 'Low' && live.length) issues.push(`${r.risk_id}: likelihood Low but linked task ${live.join(', ')} is blocked/overdue`);
    const words = norm(r.next_step).split(' ').filter(Boolean);
    const content = words.filter((w) => !phaseWords.has(w) && !/^\d+$/.test(w));
    const mitigation = new Set(norm(register.get(r.risk_id)?.mitigation_strategy).split(' '));
    const copied = words.length && words.filter((w) => mitigation.has(w)).length / words.length > 0.8;
    if (content.length < 5) issues.push(`${r.risk_id}: next step is not an action (“${r.next_step}”)`);
    else if (copied) issues.push(`${r.risk_id}: next step copies the register mitigation`);
    if (r.next_step_before_phase < currentPhase) issues.push(`${r.risk_id}: next step deadline Phase ${r.next_step_before_phase} has already passed`);
    return issues;
  }));
}

const useCases = (r) => (r.affected_use_cases.length ? r.affected_use_cases.join(', ') : 'Organisation-wide');
const nextStep = (r) => `${r.next_step} _(before ${phaseLabel(r.next_step_before_phase)})_`;

// Deterministic ranking: score desc, then impact, then the model's priority_rank.
function rank(risks) {
  return [...risks]
    .map((r) => ({ ...r, score: SCORE[r.likelihood] * SCORE[r.impact] }))
    .sort((x, y) => y.score - x.score || SCORE[y.impact] - SCORE[x.impact] || x.priority_rank - y.priority_rank)
    .map((r, i) => ({ ...r, rank: i + 1 }));
}

const signals = (r) => (r.related_task_ids.length
  ? r.related_task_ids.map((id) => `${id} ${tasksById.get(id)?.task_name ?? '?'} (${tasksById.get(id)?.status ?? '?'})`).join('; ')
  : '—');
const phaseLabel = (n) => (phases.has(n) ? `Phase ${n}: ${phases.get(n).phase_name}` : `Phase ${n}`);

function renderAssessment(status, a, ranked, grounding, review) {
  const top = status === 'TOP_RISKS';
  const shown = top ? ranked.slice(0, Math.max(1, a.requested_count)) : ranked;
  const f = kb.facts;
  const header = [
    `# ${top ? `Top ${shown.length} Risks` : 'Risk Assessment'} — ${kb.project.name}`,
    `_Generated by Mira · as of ${f.as_of_date} (week ${f.current_week}, ${f.current_phase}) · Sources: project_risks.csv, project_description.txt, sample_task_board.csv, project_timeline.csv_`,
    '## Summary', a.summary,
  ];

  const body = top
    ? shown.map((r) => {
      const reg = register.get(r.risk_id);
      return [
        `### ${r.rank}. ${r.risk_id} — ${reg.category}: ${reg.risk_challenge}`,
        `**Likelihood:** ${r.likelihood} · **Impact:** ${r.impact} · **Score:** ${r.score}/9 · **Most exposed:** ${phaseLabel(r.exposed_phase)} · **Owner:** ${r.owner_role}`,
        `**Why it matters now:** ${r.rationale}`,
        `_Threatens: “${r.evidence_quote}” · Use cases affected: ${useCases(r)}_`,
        `**Impact if it happens (register):** ${reg.impact}`,
        `**Live signals on the task board:** ${signals(r)}`,
        `**Mitigation (register):** ${reg.mitigation_strategy}`,
        `**Recommended next step:** ${nextStep(r)}`,
      ].join('\n\n');
    })
    : [
      '## Risk register (ranked by likelihood × impact)',
      ['| # | ID | Category | Risk | L | I | Score | Use cases affected | Most exposed | Live signals | Owner |',
        '|---|---|---|---|---|---|---|---|---|---|---|',
        ...shown.map((r) => {
          const reg = register.get(r.risk_id);
          return `| ${r.rank} | ${r.risk_id} | ${cell(reg.category)} | ${cell(reg.risk_challenge)} | ${r.likelihood} | ${r.impact} | ${r.score} | ${cell(useCases(r))} | ${cell(phaseLabel(r.exposed_phase))} | ${cell(signals(r))} | ${r.owner_role} |`;
        })].join('\n'),
      '## Why each risk matters & what to do',
      shown.map((r) => {
        const reg = register.get(r.risk_id);
        return `**${r.rank}. ${r.risk_id} ${reg.category}** — ${r.rationale}  \n` +
          `_Threatens: “${r.evidence_quote}”_  \n` +
          `Impact (register): ${reg.impact}  \n` +
          `Mitigation (register): ${reg.mitigation_strategy}  \n` +
          `Next step: ${nextStep(r)}`;
      }).join('\n\n'),
    ];

  return [
    ...header,
    ...body,
    '---',
    `Grounding check: ${grounding.grounded}/${grounding.checked} risks traced to the register and source` +
      (grounding.issues.length ? `\n${grounding.issues.map((i) => `- ⚠ ${i}`).join('\n')}` : ' ✅'),
    `Review checks (task-board consistency, actionable next steps):` +
      (review.length ? `\n${review.map((i) => `- ⚠ ${i}`).join('\n')}` : ' ✅'),
  ].join('\n\n');
}

function renderClarification(c) {
  return [
    '## More information needed before I can assess risks',
    c.reason,
    '**What I have so far**', list(c.known_information),
    '**What is missing**', list(c.missing_information),
    '**Please answer these questions**',
    c.questions.map((q, i) => `${i + 1}. ${q}`).join('\n'),
    '_No risks were listed, to avoid inventing project-specific risks without project data._',
  ].join('\n\n');
}

return $input.all().map((item, i) => {
  const req = requests[i].json;
  const body = item.json.body ?? item.json;
  const headers = item.json.headers ?? {};
  const finishedAt = new Date().toISOString();
  const content = body.choices?.[0]?.message?.content ?? '';

  let output = null, parseError = null;
  try { output = JSON.parse(content); } catch (e) { parseError = e.message; }

  let markdown, grounding = null, review = [], ranked = [], shownCount = 0;
  const status = output?.status ?? 'ERROR';
  if (!output) {
    markdown = `⚠ Risk Assessor returned unparseable output (${parseError}).\n\n${content}`;
  } else if (status !== 'NEEDS_CLARIFICATION' && output.assessment) {
    // Schema returns { R01: {...}, R02: {...} }; flatten to a list keyed by risk_id.
    const a = { ...output.assessment, risks: Object.entries(output.assessment.risks).map(([risk_id, r]) => ({ risk_id, ...r })) };
    grounding = groundingCheck(a, req);
    review = reviewCheck(a.risks);
    ranked = rank(a.risks);
    shownCount = status === 'TOP_RISKS' ? Math.min(ranked.length, Math.max(1, a.requested_count)) : ranked.length;
    markdown = renderAssessment(status, a, ranked, grounding, review);
  } else {
    markdown = renderClarification(output.clarification ?? { reason: 'Insufficient detail.', known_information: [], missing_information: [], questions: [] });
  }

  // Model latency from OpenAI's header gives accurate per-call timing even when items run in sequence.
  const latencyMs = Number(headers['openai-processing-ms']) || (Date.parse(finishedAt) - Date.parse(req.started_at));
  const llmEnd = new Date(Date.parse(req.started_at) + latencyMs).toISOString();
  const usage = body.usage ?? {};
  const topRisks = ranked.slice(0, shownCount).map((r) => `${r.risk_id} (${r.likelihood}/${r.impact})`);

  return {
    json: {
      test_id: req.test_id,
      query: req.query,
      checks: req.checks,
      agent: req.agent,
      status,
      uses_project_data: req.uses_project_data,
      risk_count: shownCount,
      assessed_count: ranked.length,
      top_risks: topRisks,
      grounding,
      review,
      review_issue_count: review.length,
      markdown,
      usage: { input_tokens: usage.prompt_tokens ?? 0, output_tokens: usage.completion_tokens ?? 0, total_tokens: usage.total_tokens ?? 0 },
      trace: {
        name: 'Mira',
        start_time: req.started_at,
        end_time: finishedAt,
        inputs: { query: req.query },
        outputs: { status, response: markdown },
        tags: ['mira', 'risk', req.test_id].filter(Boolean),
        metadata: { test_id: req.test_id, agent: req.agent, status, uses_project_data: req.uses_project_data, groundedness: grounding?.score ?? null, as_of_date: kb.facts.as_of_date },
        children: [
          {
            name: req.agent,
            run_type: 'llm',
            start_time: req.started_at,
            end_time: llmEnd,
            inputs: { messages: req.openaiRequest.messages },
            outputs: body,
            model: req.openaiRequest.model,
            temperature: req.openaiRequest.temperature,
          },
          {
            name: 'Grounding Check',
            run_type: 'chain',
            start_time: llmEnd,
            end_time: finishedAt,
            inputs: { status, uses_project_data: req.uses_project_data },
            outputs: grounding ? { ...grounding, review, ranking: ranked.map((r) => `${r.rank}. ${r.risk_id} score ${r.score}`) } : { skipped: 'no assessment generated' },
          },
        ],
      },
    },
  };
});

// Reusable: converts each item's `trace` descriptor into a LangSmith /runs/batch payload.
// Descriptor: { name, start_time, end_time, inputs, outputs, tags, metadata,
//               children: [{ name, run_type, start_time, end_time, inputs, outputs, model?, temperature? }] }

const cfg = $('Config').first().json;

// UUID v7 (time-ordered), which LangSmith expects for run IDs.
function uuidv7(ms) {
  const r = (n) => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
  const ts = ms.toString(16).padStart(12, '0');
  const variant = '89ab'[Math.floor(Math.random() * 4)];
  return `${ts.slice(0, 8)}-${ts.slice(8, 12)}-7${r(3)}-${variant}${r(3)}-${r(12)}`;
}

// LangSmith dotted_order segment: YYYYMMDDTHHMMSSffffffZ + run id
const dottedTs = (iso) => iso.replace(/[-:]/g, '').replace('.', '').replace('Z', '000Z');

function usageMetadata(outputs) {
  const u = outputs?.usage ?? {};
  return { input_tokens: u.prompt_tokens ?? 0, output_tokens: u.completion_tokens ?? 0, total_tokens: u.total_tokens ?? 0 };
}

return $input.all().map(({ json }) => {
  const t = json.trace;
  const rootStart = Date.parse(t.start_time);
  const traceId = uuidv7(rootStart);
  const rootDotted = dottedTs(t.start_time) + traceId;

  const root = {
    id: traceId,
    trace_id: traceId,
    dotted_order: rootDotted,
    name: t.name,
    run_type: 'chain',
    inputs: t.inputs,
    outputs: t.outputs,
    start_time: t.start_time,
    end_time: t.end_time,
    session_name: cfg.langsmithProject,
    tags: t.tags,
    extra: { metadata: { ...t.metadata, n8n_execution_id: $execution.id } },
  };

  // Children start strictly after the root (+1 ms each) so dotted_order stays monotonic.
  const children = (t.children ?? []).map((c, idx) => {
    const startMs = Math.max(Date.parse(c.start_time), rootStart + idx + 1);
    const start = new Date(startMs).toISOString();
    const end = new Date(Math.max(Date.parse(c.end_time), startMs)).toISOString();
    const id = uuidv7(startMs);
    const run = {
      id,
      trace_id: traceId,
      parent_run_id: traceId,
      dotted_order: `${rootDotted}.${dottedTs(start)}${id}`,
      name: c.name,
      run_type: c.run_type,
      inputs: c.inputs,
      outputs: c.outputs,
      start_time: start,
      end_time: end,
      session_name: cfg.langsmithProject,
    };
    if (c.run_type === 'llm') {
      run.outputs = { ...c.outputs, usage_metadata: usageMetadata(c.outputs) };
      run.extra = {
        metadata: { ls_provider: 'openai', ls_model_name: c.model, ls_model_type: 'chat', ls_temperature: c.temperature },
        invocation_params: { model: c.model, temperature: c.temperature },
      };
    }
    return run;
  });

  return { json: { test_id: json.test_id, trace_id: traceId, batch: { post: [root, ...children] } } };
});

// Scores each agent output against its test's expectations (see Test Cases node).

const outputs = $('Risk Assessor: Format Output').all().map((i) => i.json);
const traceIds = $('LangSmith: Build Trace').all().map((i) => i.json.trace_id);

function evaluate(check, out) {
  const text = out.markdown.toLowerCase();
  switch (check.type) {
    case 'status':
      return [[].concat(check.value).includes(out.status), `status ${out.status}`];
    case 'phase_count':
      return [out.phase_count === check.value, `${out.phase_count} phases`];
    case 'field':
      return [out[check.field] === check.value, `${check.field} = ${JSON.stringify(out[check.field])}`];
    case 'judge_material_max': {
      if (out.judge_skipped) return [true, 'fact-check n/a'];
      const claims = out.judge?.unsupported_claims ?? [];
      const material = claims.filter((c) => c.severity === 'material').length;
      return [out.judge_score !== null && material <= check.value, `fact-check ${out.judge_score ?? '–'}/5 · ${material} material, ${claims.length - material} minor`];
    }
    case 'judge_min':
      if (out.judge_skipped) return [true, 'fact-check n/a'];
      return [(out.judge_score ?? 0) >= check.value, `fact-check ${out.judge_score ?? '–'}/5${out.unsupported_count ? ` (${out.unsupported_count} unsupported)` : ''}`];
    case 'grounded_min': {
      const score = out.grounding?.score ?? 0;
      return [score >= check.value, `groundedness ${(score * 100).toFixed(0)}%`];
    }
    case 'mentions_all': {
      const missing = check.value.filter((term) => !text.includes(term.toLowerCase()));
      return [missing.length === 0, missing.length ? `missing: ${missing.join(', ')}` : `mentions ${check.value.join(', ')}`];
    }
    case 'mentions_any': {
      const hit = check.value.filter((term) => text.includes(term.toLowerCase()));
      return [hit.length > 0, hit.length ? `mentions ${hit.join(', ')}` : `none of: ${check.value.join(', ')}`];
    }
    case 'not_mentions': {
      const found = check.value.filter((term) => text.includes(term.toLowerCase()));
      return [found.length === 0, found.length ? `should not mention: ${found.join(', ')}` : 'no forbidden terms'];
    }
    default:
      return [false, `unknown check ${check.type}`];
  }
}

return outputs.map((out, i) => {
  // Advisory checks (the LLM judge, ~50% measured precision) are shown as INFO and never decide the verdict.
  const results = (out.checks ?? []).map((c) => {
    const [pass, detail] = evaluate(c, out);
    return `${c.advisory ? 'INFO' : pass ? 'PASS' : 'FAIL'} – ${c.type}: ${detail}${c.advisory && !pass ? ' (review)' : ''}`;
  });
  const failed = results.filter((r) => r.startsWith('FAIL')).length;
  const graded = results.filter((r) => !r.startsWith('INFO')).length;
  return {
    json: {
      test_id: out.test_id,
      verdict: results.length === 0 ? 'NO CHECKS' : failed === 0 ? 'PASS' : 'FAIL',
      checks: results,
      checks_passed: graded - failed,
      checks_total: graded,
      status: out.status,
      tokens: out.usage.total_tokens,
      route: out.route,
      expected_route: (out.checks ?? []).find((c) => c.type === 'field' && c.field === 'route')?.value ?? null,
      groundedness: out.grounding?.score ?? null,
      judge_score: out.judge_score,
      judge_material: out.judge_skipped ? null : (out.judge?.unsupported_claims ?? []).filter((c) => c.severity === 'material').length,
      query: out.query,
      started_at: out.started_at_trace ?? null,
      ended_at: out.ended_at_trace ?? null,
      unsupported_claims: (out.judge?.unsupported_claims ?? []).map((c) => c.claim),
      langsmith_trace_id: traceIds[i],
      response: out.markdown,
      output: out.markdown, // shown as the reply when Mira runs from the Chat Trigger
    },
  };
});
